def process(mmc1) -> pd.DataFrame:
    import pandas as pd

    df = mmc1.copy()

    # Identify histologic type and the variants/Mbp column robustly
    hist_col = None
    for c in df.columns:
        if str(c).strip().lower() == 'histologic_type':
            hist_col = c
            break
    if hist_col is None:
        raise ValueError("Could not find 'Histologic_type' column in mmc1")

    variants_col = None
    for c in df.columns:
        cl = str(c).strip().lower()
        if 'variant' in cl and ('/mb' in cl or 'per mb' in cl or 'mbp' in cl):
            variants_col = c
            break
    # Fallback: common naming in these supplements
    if variants_col is None:
        for c in df.columns:
            cl = str(c).strip().lower()
            if cl in {'variants_per_mbp', 'variants per mbp', 'variants/mbp', 'variants_per_mb', 'variants/mb'}:
                variants_col = c
                break
    if variants_col is None:
        # last resort: search mutation burden style columns
        cand = [c for c in df.columns if 'mutation' in str(c).lower() and ('/mb' in str(c).lower() or 'per mb' in str(c).lower() or 'mbp' in str(c).lower())]
        if len(cand) == 1:
            variants_col = cand[0]
        else:
            raise ValueError("Could not uniquely identify a 'variants per Mbp' column. Candidates: " + str(cand[:20]))

    # Filter to serous tumors
    serous_mask = df[hist_col].astype(str).str.strip().str.lower().eq('serous')
    serous = df.loc[serous_mask, [hist_col, variants_col]].copy()

    # Coerce to numeric
    serous['variantsPerMbp'] = pd.to_numeric(serous[variants_col], errors='coerce')

    median_val = float(serous['variantsPerMbp'].dropna().median())

    return pd.DataFrame([{
        'histologic_type': 'serous',
        'variantsPerMbp_column': str(variants_col),
        'n_serous_rows': int(serous.shape[0]),
        'n_nonnull_variantsPerMbp': int(serous['variantsPerMbp'].notna().sum()),
        'median_variants_per_mbp': round(median_val, 4),
    }])
